-- === CAT_QUELTHALAS ===
-- LOR'THEMAR THERON --
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].name = "Lor'themar Theron"
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].aliases = {"Lor'themar"}
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].race = "Elfo de sangre"
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].lore = [[
Siendo un Forestal de corazón, Lor'themar Theron no eligió liderar a los elfos de sangre. Cuando Quel'thalas cayó por la Plaga en la Tercera Guerra, fue nombrado como regente por el Príncipe Kael'thas, en parte debido a la falta de otros candidatos supervivientes. 

Fue forzado a tomar decisiones difíciles, como aliar a los elfos de sangre con la Horda, exiliar a los altos elfos para combatir los disturbios y liderar la batalla contra Kael'thas luego de la traición del príncipe. El pragmatismo de Lor'themar y su astucia estratégica lo convirtieron, no obstante, en un líder inspirador, ganándole el respeto de amigos y enemigos por igual. 

Un firme defensor de la paz, Lor'themar ahora sirve como regente de Quel'thalas y como miembro del Consejo de la Horda. Su lealtad permanece primero y por encima de todo en su gente. 

Ahora, con Quel'thalas en peligro una vez más, no se detendrá ante nada para defender a su gente y su ciudad en contra de las fuerzas invasoras del Vacío.
]]
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].zones = {"Ciudad de Lunargenta", "Bosque Canción Eterna", "Isla de Quel'Danas", "Harandar"}
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].source = "Karstan"
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].timeline = IMAGOdb.timelines.LORTHEMAR_THERON

-- VAREESA WINDRUNNER --
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].name = "Vereesa Windrunner"
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].aliases = {"Vereesa"}
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].race = "Alta elfa"
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].lore = [[Vereesa es la más joven de las hermanas Brisaveloz. Su vida cambió cuando la Horda llegó a Azeroth y no pudo evitar la muerte de su hermano menor, Lirath. Crió a Arathor, el hijo de su hermana Alleria, y ayudó al mago Rhonin en su misión para rescatar a la dragona aspecto Alextrasza. Sin embargo, su vida fue marcada por la tragedia cuando se encontró completamente sola luego de la muerte de todo lo que conocía a manos de Arthas y la muerte de su esposo Rhonin en la destrucción de Theramore. Esto la llevó a cometer actos que afectarían su reputación con los elfos de sangre para siempre.]]
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].zones = {"Bosque Canción Eterna", "Isla de Quel'Danas", "Ciudad de Lunargenta"}
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].source = "Karstan"
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].timeline = IMAGOdb.timelines.VEREESA_WINDRUNNER

-- FIRST ARCANIST THALYSSRA --
IMAGOdb.npcs.CAT_QUELTHALAS["first_arcanist_thalyssra_midnight"].name = "Primera Arcanista Thalyssra"
IMAGOdb.npcs.CAT_QUELTHALAS["first_arcanist_thalyssra_midnight"].aliases = {"Thalyssra"}
IMAGOdb.npcs.CAT_QUELTHALAS["first_arcanist_thalyssra_midnight"].race = "Nocheterna"
IMAGOdb.npcs.CAT_QUELTHALAS["first_arcanist_thalyssra_midnight"].lore = [[La Primera Arcanista Thalyssra es la líder de los elfos Nocheterna. 

Tras ser exiliada de su ciudad natal de Suramar por su líder corrupta, la Primera Arcanista Thalyssra liberó a los Shal'dorei de su adicción al poder de la Fuente de la Noche, convirtiéndose en su líder luego del saqueo de Suramar. Ella ahora gobierna a su gente mano a mano con los elfos de sangre de Lor'themar Theron, uniendo ambas culturas a través de la unidad de la Horda y de su matrimonio.]]
IMAGOdb.npcs.CAT_QUELTHALAS["first_arcanist_thalyssra_midnight"].zones = {"Suramar", "Ciudad de Lunargenta", "Isla de Quel'Danas"}
IMAGOdb.npcs.CAT_QUELTHALAS["first_arcanist_thalyssra_midnight"].source = "Karstan"
IMAGOdb.npcs.CAT_QUELTHALAS["first_arcanist_thalyssra_midnight"].timeline = IMAGOdb.timelines.FIRST_ARCANIST_THALYSSRA

-- ASTALOR BLOODSWORN --
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].name = "Astalor Bloodsworn"
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].aliases = {"Astalor", "Magister Jurasangre"}
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].race = "Elfo de sangre"
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].lore = [[Cofundador de los Caballeros de Sangre de Lunargenta, el mago Astalor Jurasangre siempre ha buscado formas ingeniosas de ayudar a su pueblo. Cuando Kael'thas envió a Lunargenta al naaru cautivo M'uru, fue Astalor quien aconsejó que, en lugar de limitarse a alimentarse de la criatura sagrada, drenaran y utilizaran su energía para otorgar a los elfos de sangre el poder de convertirse en paladines. 

Ante la amenaza de la Tormenta del Vacío sobre Lunargenta, Astalor vuelve a recurrir a métodos poco convencionales para combatirla: dar caza a individuos peligrosos y cosechar su angustia para transformarla en una poderosa fuente de energía. Está por ver qué resultados conseguirá...]]
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].zones = {"Ciudad de Lunargenta", "Bosque Canción Eterna"}
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].timeline = IMAGOdb.timelines.ASTALOR_BLOODSWORN


-- === CAT_LIGHT ===
IMAGOdb.npcs.CAT_LIGHT["danath_trollbane_midnight"].name = "Danath Trollbane"
IMAGOdb.npcs.CAT_LIGHT["danath_trollbane_midnight"].aliases = {}
IMAGOdb.npcs.CAT_LIGHT["danath_trollbane_midnight"].race = "Humano"
IMAGOdb.npcs.CAT_LIGHT["danath_trollbane_midnight"].lore = [[name="Danath Aterratrols"

El legítimo gobernante del reino de Stromgarde y antiguo héroe de la Alianza. Danath Aterratrols ha luchado y sangrado por la humanidad desde los días de la Segunda Guerra. Miembro de los Hijos de Lothar, Danath forjó estrechos lazos con sus compatriotas en su estancia más allá del Portal Oscuro. Tras regresar a Azeroth para asumir su título como Rey de Stromgarde, Danath busca guiar a su pueblo de vuelta a su antigua gloria.]]
IMAGOdb.npcs.CAT_LIGHT["danath_trollbane_midnight"].zones = {"Arcantina", "Estepas Ardientes"}
IMAGOdb.npcs.CAT_LIGHT["danath_trollbane_midnight"].source = "Karstan"
IMAGOdb.npcs.CAT_LIGHT["danath_trollbane_midnight"].timeline = IMAGOdb.timelines.DANATH_TROLLBANE

-- ALONSUS FAOL --
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].name = "Archbishop Alonsus Faol"
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].aliases = {"Alonsus", "Alonsus Faol"}
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].race = "No-muerto"
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].lore = [[Antiguamente arzobispo de la Iglesia de la Luz Sagrada, Alonsus Faol fue, posiblemente, el hombre más venerado de Lordaeron. Cuando la Horda invadió Azeroth por la primera vez, fue Faol quien entrenó y consagró a los primeros paladines, una decisión que aseguró la victoria de la Alianza en la guerra. Orgulloso de sus logros, el anciano obispo murió en paz.

Arthas Menethil no le permitió descansar y lo resucitó como un siervo descerebrado de la Plaga. Cuando Alonsus finalmente consiguió liberarse del control del paladín caído, la Alianza lo rechazó, los sirvientes radicales de la Luz lo persiguieron y él mismo sufría un dolor terrible cada vez que utilizaba la magia sagrada. Durante años, se apartó del mundo.

Cuando la Legión invadió Azeroth, Alonsus no pudo quedarse de brazos cruzados. Al frente del Cónclave, unificando las distintas órdenes sacerdotales, ayudó a encontrar diversos artefactos con los que combatir a los demonios. Uno de ellos era la Daga del Imperio Negro: Xal'atath. 

Ahora, Alonsus lucha por la Fuente de la Luz para enmendar su error.]]
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].zones = {"Lunargenta", "Isla de Quel'Danas", "Plaza del Parhelio", "Estepas Ardientes", "Tierras Altas de Arathi", "Tierras de la Peste del Este"}
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].timeline = IMAGOdb.timelines.ALONSUS_FAOL

