-- === CAT_VOID ===
-- XAL'ATATH --
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].name = "Xal'atath"
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].aliases = {"La Presagista", "Daga del Imperio Negro"}
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].race = "Desconocido"
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].lore = [[Su sonrisa es una amenaza, sus susurros son advertencias y sus promesas son mentiras. La Presagista del Vacío ha manipulado a los habitantes de Azeroth durante milenios y, con la misma facilidad con la que elevaba a sus aliados a cotas de gran poder, los abandonaba a su suerte.

Durante incontables años, estuvo atrapada en el interior de la Daga del Imperio Negro, un castigo impuesto por los Dioses Antiguos después de que se opusiera a ellos. Con la ayuda de los Campeones de Azeroth, ahora vuelve a ser libre.

Xal'atath busca el alma-mundo y, con el Corazón Oscuro potenciado, ataca a la Fuente del Sol en un intento por alcanzarla. Sigue siendo un misterio por qué la persigue, e incluso sus propios orígenes están envueltos en ambigüedad. Lo único que está claro es que debe ser detenida a cualquier precio. El destino del universo podría depender de los Campeones de Azeroth.]]
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].zones = {"Isla de Quel'Danas", "Tormenta del Vacío", "Aguja del Vacío"}
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].timeline = IMAGOdb.timelines.XAL_ATATH

