-- === CAT_NEUTRAL ===
-- EITRIGG --
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].name = "Eitrigg"
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].aliases = {}
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].race = "Orco"
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].lore = [[Veterano de mil batallas. Eitrigg es uno de los orcos más importantes en la historia de la Horda, uno de los pocos que aún recuerdan los tiempos oscuros del pasado en donde se cometieron incontables horrores contra los inocentes. Peleó por la Antigua Horda en Draenor y en la Nueva Horda hasta el día de hoy en Azeroth, forjando un vínculo con Tirion Vadín, un humano, luego de años de guerra entre las dos razas. Sirvió como consejero de los jefes de guerra Thrall y Garrosh, y se levantó cuando fue necesario contra el último y Sylvanas Brisaveloz. Eventualmente, fue admitido dentro de los Hijos de Lothar como un símbolo de que el honor puede venir de cualquiera.]]
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].zones = {"Tierras Altas de Arathi", "Arcantina", "Estepas Ardientes"}
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].source = "Karstan"
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].timeline = IMAGOdb.timelines.EITRIGG

-- ALLERIA WINDRUNNER --
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].name = "Alleria Windrunner"
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].aliases = {"Alleria"}
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].race = "Elfa del Vacío"
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].lore = [[Conocida por los habitantes de Azeroth como una de las mayores heroínas de guerra de la Alianza, Alleria ha luchado en la Segunda Guerra y en la cruzada milenaria contra la Legión Ardiente. Es muchas cosas - madre, pareja, heroína, hermana mayor, - pero por encima de todo es una cazadora. Todo queda relegado a un segundo plano ante la misión que se avecina, y ningún precio es demasiado alto cuando se trata de garantizar la seguridad de su mundo.

La guerra es la única vida que conoce, y encuentra más consuelo y familiaridad en el campo de batalla que en tiempos de paz. Cuando perdió a su hermano menor y a sus padres durante la guerra contra la Horda, Alleria se culpó a sí misma y se lanzó temerariamente al combate, buscando un propósito a través de la violencia. Nunca llegó a recuperarse por completo del trauma causado por aquellas pérdidas. Aunque formó una familia junto con Turalyon y su hijo Arator, es incapaz de volver a abrirse emocionalmente, incluso cuando ver cómo ambos hombres se convierten en extraños le está destrozando por dentro.

Mientras luchaba contra la Legión Ardiente, Alleria encontró un arma en el Vacío. Fue imbuida con la esencia de la naaru caída L'ura y ahora emplea sus poderes oscuros por el bien de Azeroth. Siempre al borde de la locura y acosada constantemente por susurros que asaltan su mente, Alleria ha puesto ahora su mente en dar caza a Xal'atath. Como ocurre con todas sus cacerías, la persecución se ha convertido en una obsesión, y no descansará hasta ver a su enemiga derrotada.]]
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].zones = {"Tormenta del Vacío", "Aguja del Vacío"}
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].timeline = IMAGOdb.timelines.ALLERIA_WINDRUNNER

-- DECIMUS --
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].name = "Decimus"
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].aliases = {}
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].race = "Domanaar"
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].lore = [[Carismático, peligroso, malicioso: todos estos adjetivos podrían utilizarse para describir a Decimus. Como todos los domanaar de la Tormenta del Vacío, estaba sometido a Xal'atath y reconocía en ella a un ser más poderoso. 

Sin embargo, Decimus no tenía intención de seguir sirviendo durante mucho más tiempo, y ahora se encuentra inmerso en un peligroso juego, con los Campeones de Azeroth como piezas sobre el tablero.]]
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].zones = {"Tormenta del Vacío", "Val", "Naigtal"}
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].timeline = IMAGOdb.timelines.DECIMUS

